INSERT INTO trading_config_versions(id,version,snapshot,created_at) SELECT 'TRADING-CONFIG-v'||(SELECT COALESCE(MAX(version),0)+1 FROM trading_config_versions),(SELECT COALESCE(MAX(version),0)+1 FROM trading_config_versions),json_set(snapshot,'$.publicationPolicy',json('{"riskVeto":true,"bossVeto":true,"requireAiQuorum":true,"minConfidence":60,"blockLowRR":true}')),CAST(strftime('%s','now') AS INTEGER)*1000 FROM trading_config_versions WHERE id=(SELECT value FROM system_state WHERE key='active_config') AND json_type(snapshot,'$.publicationPolicy') IS NULL;
UPDATE system_state SET value=(SELECT id FROM trading_config_versions ORDER BY version DESC LIMIT 1) WHERE key='active_config' AND EXISTS (SELECT 1 FROM trading_config_versions WHERE id=system_state.value AND json_type(snapshot,'$.publicationPolicy') IS NULL);
